class ParamOut(TypedDict):
    """A param is a field, as entity types' are, with its default and limits."""
    #: Whoever it names is assigned the record (ADR 0122): it's on their My work while the record's state field `assignment_field` is in one of `assignment_states`, and they're told.
    assignment: bool
    #: The state field (ADR 0125) whose states say when it's their work. Null: it's their work in every state.
    assignment_field: str | None
    #: The states of `assignment_field` in which it's their work.
    assignment_states: list[str]
    #: Set only by actions.
    computed: bool
    #: What it is when not given.
    default: NotRequired[Any]
    description: str | None
    #: Its plugin is detached (ADR 0091): it keeps its value, which can't change.
    detached: bool
    display_offset: float | None
    #: With a display unit: shown as value * display_scale + display_offset.
    display_scale: float | None
    display_unit: str | None
    display_unit_symbol: str | None
    #: Can be set once, and can't change after.
    immutable: bool
    #: State fields (ADR 0125): the state new records start in. Null otherwise.
    initial: str | None
    #: Quantities: common units values can be given in. Any convertible UCUM unit works.
    input_units: list[UnitOption]
    #: Lists: the type of each item.
    items: str | None
    label: str
    #: Where a value leads in another system: an https URL with `{value}` in it, for the value, URL-encoded.
    link: str | None
    max: float | None
    max_length: int | None
    min: float | None
    min_length: int | None
    name: str
    pattern: str | None
    #: The plugin that defines the field.
    plugin: str
    #: Its registry entry's (ADR 0115), every holding project's: part of its identity, derived from it, or a fact its registrars curate. A fact is set while it's empty; after that only a registrar changes it. Null: each project's own.
    registry: NotRequired[Literal['identity', 'derived', 'fact'] | None]
    required: bool
    #: For a field naming people (`person`, or a list of them): the lab role whoever it names must hold in the record's project (ADR 0116), or null for anyone who can read it.
    role: str | None
    #: What people call that role.
    role_label: str | None
    #: A list of rows (`items` is `row`, ADR 0137): each row's fields, and what each role takes. Its value is a list of objects, one per row. Null otherwise.
    row: NotRequired[RowOut | None]
    #: State fields (ADR 0125): its states, in order. It's set on its own, with POST /entities/{ref}/states/{field}, never with other values. Empty otherwise.
    states: list[StateOut]
    #: References: the types they may refer to, any one of them or one of its subtypes (ADR 0136); `iki/core.Entity` for any entity. For a list, its items'. Empty otherwise.
    to: list[str]
    type: str
    #: No two entities in a project have the same value, such as a LIMS record's ID.
    unique: bool
    #: Quantities: the UCUM unit values are in.
    unit: str | None
    #: The unit as people write it, such as Å for Ao.
    unit_symbol: str | None
    #: Enums, and lists of them: the allowed values (for a list, its items').
    values: list[str]


